let user = { name: "Alex", age: 25 };

let proxy = new Proxy(user, {
  get(target, prop) {
    console.log(`Reading ${prop}`);
    return prop in target ? target[prop] : "Property not found";
  },
  set(target, prop, value) {
    console.log(`Setting ${prop} = ${value}`);
    target[prop] = value;
    return true;
  }
});

console.log(proxy.name);  // "Reading name" → "Alex"
console.log(proxy.x);     // "Reading x" → "Property not found"
proxy.age = 30;           // "Setting age = 30"

let user = { name: "Alex", age: 25 };

let proxy = new Proxy(user, {
  get(target, prop, receiver) {
    console.log(`Accessed: ${prop}`);
    return Reflect.get(target, prop, receiver);
  },
  set(target, prop, value, receiver) {
    if (typeof value === "string" && prop === "name") {
      value = value.toUpperCase();
    }
    return Reflect.set(target, prop, value, receiver);
  }
});

console.log(proxy.name);  // "ALEX"
proxy.name = "Sam";
console.log(proxy.name);  // "SAM"

function reactive(obj, onChange) {
  return new Proxy(obj, {
    set(target, prop, value) {
      let oldValue = target[prop];
      target[prop] = value;
      if (oldValue !== value) {
        onChange(prop, value, oldValue);
      }
      return true;
    }
  });
}

let state = reactive({ count: 0, name: "Alex" }, (prop, newVal, oldVal) => {
  console.log(`${prop}: ${oldVal} → ${newVal}`);
});

state.count = 1;   // "count: 0 → 1"
state.name = "Sam"; // "name: Alex → Sam"
state.count = 1;   // no log (same value)
